.darma-loader-darma-b14-bike-chain-drive { --accent: var(--loader-color, #64748b); --accent-2: var(--loader-secondary-color, #0f172a); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .62); position: relative; }
.darma-loader-darma-b14-bike-chain-drive::before { content: ''; position: absolute; top: 19%; left: 22%; width: 58%; height: 6%; background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 34%, var(--accent-2)) 0 calc(var(--loader-size, 124px) * .022), transparent calc(var(--loader-size, 124px) * .022) calc(var(--loader-size, 124px) * .046)); animation: darma-loader-darma-b14-bike-chain-drive-chain-top calc(var(--loader-speed, 1s) * .8) linear infinite; }
.darma-loader-darma-b14-bike-chain-drive::after { content: ''; position: absolute; bottom: 19%; left: 22%; width: 58%; height: 6%; background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 34%, var(--accent-2)) 0 calc(var(--loader-size, 124px) * .022), transparent calc(var(--loader-size, 124px) * .022) calc(var(--loader-size, 124px) * .046)); animation: darma-loader-darma-b14-bike-chain-drive-chain-bottom calc(var(--loader-speed, 1s) * .8) linear infinite; }
.darma-loader-darma-b14-bike-chain-drive span { position: absolute; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent) 0 11deg, color-mix(in srgb, #000 26%, var(--accent)) 11deg 22deg); box-shadow: inset 0 0 0 calc(var(--loader-size, 124px) * .045) color-mix(in srgb, #fff 24%, var(--accent-2)); animation: darma-loader-darma-b14-bike-chain-drive-sprocket calc(var(--loader-speed, 1s) * 2) linear infinite; }
.darma-loader-darma-b14-bike-chain-drive span:nth-child(1) { left: 2%; top: 11%; width: calc(var(--loader-size, 124px) * .4); height: calc(var(--loader-size, 124px) * .4); }
.darma-loader-darma-b14-bike-chain-drive span:nth-child(2) { right: 2%; top: 22%; width: calc(var(--loader-size, 124px) * .26); height: calc(var(--loader-size, 124px) * .26); animation-duration: calc(var(--loader-speed, 1s) * 1.3); }
@keyframes darma-loader-darma-b14-bike-chain-drive-sprocket { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b14-bike-chain-drive-chain-top { to { background-position: calc(var(--loader-size, 124px) * .046) 0; } }
@keyframes darma-loader-darma-b14-bike-chain-drive-chain-bottom { to { background-position: calc(var(--loader-size, 124px) * -.046) 0; } }

